from collections import deque
from hypothesis import strategies as st

@st.composite
def gen(draw):
    H = draw(st.integers(1, 5))
    W = draw(st.integers(2, 5))
    N = H * W
    s = draw(st.integers(0, N - 1))
    g = draw(st.integers(0, N - 1).filter(lambda x: x != s))
    others = [c for c in range(N) if c not in (s, g)]
    k = draw(st.integers(0, min(4, len(others))))
    if k > 0:
        candies = draw(st.lists(st.sampled_from(others), min_size=k, max_size=k, unique=True))
    else:
        candies = []
    cset = set(candies)
    wall_flags = draw(st.lists(st.booleans(), min_size=N, max_size=N))
    T = draw(st.integers(1, 20))
    grid = []
    for i in range(H):
        row = []
        for j in range(W):
            c = i * W + j
            if c == s:
                row.append('S')
            elif c == g:
                row.append('G')
            elif c in cset:
                row.append('o')
            elif wall_flags[c] and draw(st.booleans()):
                row.append('#')
            else:
                row.append('.')
        grid.append(''.join(row))
    return f"{H} {W} {T}\n" + "\n".join(grid) + "\n"

def validate(inp):
    lines = inp.split("\n")
    # drop trailing empty lines produced by the final newline
    while lines and lines[-1] == "":
        lines.pop()
    if not lines:
        return False
    head = lines[0].split()
    if len(head) != 3:
        return False
    H, W, T = int(head[0]), int(head[1]), int(head[2])
    if not (1 <= H <= 300 and 1 <= W <= 300 and 1 <= T <= 2 * 10**6):
        return False
    if len(lines) != H + 1:
        return False
    grid = lines[1:]
    cnt = {'S': 0, 'G': 0, 'o': 0}
    for row in grid:
        if len(row) != W:
            return False
        for ch in row:
            if ch not in "SGo.#":
                return False
            if ch in cnt:
                cnt[ch] += 1
    return cnt['S'] == 1 and cnt['G'] == 1 and cnt['o'] <= 18

