    S = G = None
    cands = []
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if c == 'S':
                S = (i, j)
            elif c == 'G':
                G = (i, j)
            elif c == 'o':
                cands.append((i, j))
    nodes = [S] + cands + [G]
    INF = float('inf')

    def bfs(src):
        dist = [[INF] * W for _ in range(H)]
        dist[src[0]][src[1]] = 0
        dq = deque([src])
        while dq:
            x, y = dq.popleft()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and dist[nx][ny] == INF:
                    dist[nx][ny] = dist[x][y] + 1
                    dq.append((nx, ny))
        return dist

    # d[a][b] = shortest distance from node a to node b (indices into nodes)
    m = len(nodes)
    d = [[INF] * m for _ in range(m)]
    for a in range(m):
        dist = bfs(nodes[a])
        for b in range(m):
            x, y = nodes[b]
            d[a][b] = dist[x][y]

    k_total = len(cands)
    gi = m - 1
    for k in range(k_total, -1, -1):
        for combo in combinations(range(1, 1 + k_total), k):
            for perm in permutations(combo):
                total = 0
                prev = 0
                for idx in perm:
                    total += d[prev][idx]
                    prev = idx
                total += d[prev][gi]
                if total <= T:
                    return str(k)
    return "-1"
